package com.sumedha.commerce.auth.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="email_verification_tokens") public class EmailVerificationToken { @Id @Column(name="verification_id") private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="token_hash",nullable=false,unique=true) private String tokenHash; @Column(name="expiry_time",nullable=false) private Instant expiryTime; @Column(nullable=false) private boolean used; @Column(name="created_at",nullable=false) private Instant createdAt; protected EmailVerificationToken(){} public EmailVerificationToken(User u,String h,Instant e){id=UUID.randomUUID();user=u;tokenHash=h;expiryTime=e;createdAt=Instant.now();} public boolean usable(){return !used&&expiryTime.isAfter(Instant.now());} public User getUser(){return user;} public void use(){used=true;} }
